"""Runtime support for vecDSL programs generated for Oracle AI Database 26ai, through python-oracledb in thin mode. Generated by
vecDSL 7. Do not edit.

Every statement arrives as SQL text with positional bind variables (:1, :2, ... in textual order), identical in the Python,
TypeScript and Java programs. Lists and objects are bound as JSON text in CLOB variables; strings, numbers, booleans and None as
themselves. Queries return one JSON text per row (JSON_OBJECT ... RETURNING CLOB), which is decoded here. Each call is one
transaction: its statements run, then COMMIT (DDL statements commit by themselves); a failure rolls back.
"""

from __future__ import annotations

import json
import math
import os
import re
import unicodedata
from importlib.metadata import PackageNotFoundError, version
from typing import Any, NoReturn, Sequence

SDK_PACKAGE = "oracledb"
SDK_MIN = "{{sdk.python.min}}"
SDK_MAX = "{{sdk.python.max}}"

_DIGITS = 6
_BATCH = 500
_CONNECT_TIMEOUT = 10.0
_CALL_TIMEOUT_MS = 60000
_TEXT_RESERVED = frozenset(["ABOUT", "ACCUM", "AND", "BT", "BTG", "BTI", "BTP", "EQUIV", "FUZZY", "HASPATH", "INPATH", "MDATA",
                            "MINUS", "NEAR", "NOT", "NT", "NTG", "NTI", "NTP", "OR", "PT", "RT", "SQE", "SYN", "TR", "TRSYN",
                            "TT", "WITHIN"])


class UnsupportedFeature(NotImplementedError):
    pass


def _version_tuple(text: str) -> tuple[int, ...]:
    parts = []
    for token in re.split(r"[.+\-]", text.lstrip("v")):
        if not token.isdigit():
            break
        parts.append(int(token))
    return tuple(parts)


def requirement() -> str:
    return f"{SDK_PACKAGE}>={SDK_MIN},<{SDK_MAX}"


def check_sdk() -> str:
    try:
        installed = version(SDK_PACKAGE)
    except PackageNotFoundError as error:
        raise ImportError(f"{SDK_PACKAGE} is not installed; install '{requirement()}'") from error
    if not _version_tuple(SDK_MIN) <= _version_tuple(installed) < _version_tuple(SDK_MAX):
        raise ImportError(f"{SDK_PACKAGE} {installed} is not supported; install '{requirement()}'")
    return installed


check_sdk()

import oracledb  # noqa: E402

oracledb.defaults.fetch_lobs = False


def unsupported(vendor: str, feature: str) -> NoReturn:
    raise UnsupportedFeature(f"{feature} is not supported for target {vendor}")


def env(name: str) -> str:
    value = os.environ.get(name)
    if value is None:
        raise KeyError(f"environment variable {name} is not set")
    return value


class Client:
    """The database endpoint (Easy Connect string), the user and one connection; the password comes from the environment."""

    def __init__(self, dsn: str, user: str, password_variable: str, timeout: float | None = None) -> None:
        if "@" in dsn or "://" in dsn:
            raise ValueError(f"expected an Easy Connect string host:port/service without credentials, got {dsn!r}")
        self.dsn = dsn
        self.user = user
        self.password = os.environ.get(password_variable)
        if self.password is None:
            raise KeyError(f"environment variable {password_variable} is not set; it holds the password of {user}")
        self.call_timeout = int(timeout * 1000) if timeout else _CALL_TIMEOUT_MS
        self._connection: oracledb.Connection | None = None

    def connection(self) -> oracledb.Connection:
        if self._connection is None:
            self._connection = oracledb.connect(user=self.user, password=self.password, dsn=self.dsn,
                                                tcp_connect_timeout=_CONNECT_TIMEOUT)
            self._connection.call_timeout = self.call_timeout
        return self._connection

    def close(self) -> None:
        if self._connection is not None:
            self._connection.close()
            self._connection = None


def connect(dsn: str, user: str, password_variable: str = "VECDSL_ORACLEDB_PASSWORD", timeout: float | None = None) -> Client:
    return Client(dsn, user, password_variable, timeout)


def _plain(value: Any) -> Any:
    """Integral floats as integers, so that JSON text reads 35, not 35.0, in every host language."""
    if isinstance(value, float) and value.is_integer() and math.isfinite(value) and abs(value) < 1e15:
        return int(value)
    if isinstance(value, (list, tuple)):
        return [_plain(item) for item in value]
    if isinstance(value, dict):
        return {str(key): _plain(item) for key, item in value.items()}
    return value


def _bind(value: Any) -> Any:
    """A bind value: lists and objects as JSON text, integral floats as integers, everything else as it is."""
    if isinstance(value, (list, tuple, dict)):
        return json.dumps(_plain(value), separators=(",", ":"), ensure_ascii=False)
    return _plain(value)


def _value(value: Any) -> Any:
    """Result values in one form for every host language: floats rounded, integral floats as integers."""
    if isinstance(value, float):
        rounded = round(value, _DIGITS)
        return int(rounded) if rounded.is_integer() else rounded
    if isinstance(value, list):
        return [_value(item) for item in value]
    if isinstance(value, dict):
        return {key: _value(item) for key, item in value.items()}
    return value


def _run(cursor: oracledb.Cursor, sql: str, params: Sequence[Any]) -> list[Any] | int:
    """Executes one statement: the decoded JSON rows of a query, else the number of rows a DML statement changed."""
    sizes = [oracledb.DB_TYPE_CLOB if isinstance(value, (list, tuple, dict)) else None for value in params]
    if any(size is not None for size in sizes):
        cursor.setinputsizes(*sizes)
    cursor.execute(sql, [_bind(value) for value in params])
    if cursor.description is None:
        return cursor.rowcount
    return [None if row[0] is None else _value(json.loads(row[0])) for row in cursor.fetchall()]


def _transaction(client: Client, steps: Sequence[dict[str, Any]], isolation: str | None = None,
                 settings: dict[str, str] | None = None) -> list[list[Any] | int]:
    connection = client.connection()
    timeout = (settings or {}).get("call_timeout")
    connection.call_timeout = int(timeout) if timeout else client.call_timeout
    try:
        with connection.cursor() as cursor:
            if isolation == "serializable":
                cursor.execute("SET TRANSACTION ISOLATION LEVEL SERIALIZABLE")
            results = [_run(cursor, step["sql"], step.get("params", ())) for step in steps]
        connection.commit()
        return results
    except BaseException:
        connection.rollback()
        raise
    finally:
        connection.call_timeout = client.call_timeout


def _counts(step: dict[str, Any], changed: int) -> dict[str, int]:
    result = {step["counter"]: changed}
    if "skipped" in step:
        result["skipped"] = len(step["params"][int(step["skipped"])]) - changed
    return result


def query(client: Client, sql: str, params: Sequence[Any] = (), settings: dict[str, str] | None = None) -> list[Any]:
    """The JSON values of a query's rows."""
    rows = _transaction(client, [{"sql": sql, "params": params}], settings=settings)[0]
    return rows if isinstance(rows, list) else []


def value(client: Client, sql: str, params: Sequence[Any] = (), settings: dict[str, str] | None = None) -> Any:
    """The JSON value of the first row, or None."""
    rows = query(client, sql, params, settings)
    return rows[0] if rows else None


def exists(client: Client, sql: str, params: Sequence[Any] = ()) -> bool:
    """Whether the count a query returns is above zero."""
    return bool(value(client, sql, params))


def modify(client: Client, sql: str, counter: str, params: Sequence[Any] = (), skipped: int | None = None) -> dict[str, int]:
    """A DML statement: {counter: changed rows}, and for an insert that ignores conflicts the records it skipped."""
    step: dict[str, Any] = {"sql": sql, "params": params, "counter": counter}
    if skipped is not None:
        step["skipped"] = skipped
    changed = _transaction(client, [step])[0]
    return _counts(step, changed if isinstance(changed, int) else 0)


def execute(client: Client, steps: Sequence[dict[str, Any]]) -> None:
    """DDL statements and PL/SQL blocks in order; Oracle commits each DDL statement."""
    _transaction(client, steps)


def transaction(client: Client, steps: Sequence[dict[str, Any]], isolation: str | None = None) -> list[Any]:
    """The statements of a vecDSL transaction in one Oracle transaction; any failure rolls back all of them."""
    results: list[Any] = []
    for step, outcome in zip(steps, _transaction(client, steps, isolation)):
        if step.get("op") == "modify":
            results.append(_counts(step, outcome if isinstance(outcome, int) else 0))
        elif step.get("op") == "value":
            results.append(outcome[0] if isinstance(outcome, list) and outcome else None)
        else:
            results.append(outcome)
    return results


def read_records(client: Client, location: str) -> list[dict[str, Any]]:
    """Records of a local JSON array or JSON Lines file (file:// URI or path)."""
    path = location[len("file://"):] if location.startswith("file://") else location
    with open(path, encoding="utf-8") as handle:
        text = handle.read()
    stripped = text.lstrip()
    if stripped.startswith("["):
        return json.loads(stripped)
    return [json.loads(line) for line in text.splitlines() if line.strip()]


def import_file(client: Client, sql: str, location: str, params: Sequence[Any], rows: int, counter: str,
                batch_size: int = _BATCH) -> dict[str, int]:
    """A local file written in batches by one statement (the batch is the parameter at position rows), in one transaction."""
    records = read_records(client, location)
    steps = []
    for start in range(0, len(records), batch_size):
        values = list(params)
        values[int(rows)] = records[start:start + batch_size]
        steps.append({"sql": sql, "params": values})
    changed = sum(count for count in _transaction(client, steps) if isinstance(count, int))
    return {counter: changed}


def _words(text: str) -> list[str]:
    """The words of a text: runs of letters, digits and underscores (Unicode categories L and N)."""
    words, current = [], []
    for character in text:
        if character == "_" or unicodedata.category(character)[0] in "LN":
            current.append(character)
        elif current:
            words.append("".join(current))
            current = []
    if current:
        words.append("".join(current))
    return words


def text_query(client: Client | None, text: str, mode: str, stem: bool = False, fuzzy: bool = False, span: int | None = None) -> str:
    """An Oracle Text query of the words of an input: all (AND), any (ACCUM), a phrase, or the words NEAR each other in order
    within span words; fuzzy expands each word of three or more characters with FUZZY. No operator of the input survives."""
    words = _words(text or "")
    if not words:
        raise ValueError("a keyword search needs at least one word of letters or digits")
    if mode == "phrase":
        if span is None or len(words) == 1:
            return "{" + " ".join(words) + "}"
        return "NEAR((" + ", ".join("{" + word + "}" for word in words) + "), " + str(span) + ", TRUE)"
    terms = [_term(word, stem, fuzzy) for word in words]
    return (" ACCUM " if mode == "any" else " AND ").join(terms)


def _term(word: str, stem: bool, fuzzy: bool) -> str:
    if word.upper() in _TEXT_RESERVED:
        return "{" + word + "}"
    if fuzzy and len(word) >= 3:
        return "fuzzy(" + word + ")"
    return "$" + word if stem else word


def wildcard_pattern(client: Client | None, pattern: str) -> str:
    """A LIKE pattern (ESCAPE '\\') of a wildcard: * any characters, ? one character, everything else literal."""
    escaped = pattern.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")
    return escaped.replace("*", "%").replace("?", "_")
